-- EduOS 37.8.0: opaque public webhook endpoint credentials.
-- The raw endpoint token is generated by the application and shown once. Only
-- its SHA-256 digest is stored. Public requests resolve that digest through a
-- narrow SECURITY DEFINER function; no tenant ID or provider is trusted from
-- request headers/body, and encrypted provider credentials never leave SQL
-- except to the trusted application runtime after a valid token match.

CREATE TABLE commerce_webhook_endpoints (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  district_id uuid NOT NULL REFERENCES districts(id),
  processor text NOT NULL CHECK(processor IN ('paypal','square','btcpay')),
  token_sha256 text NOT NULL UNIQUE CHECK(token_sha256 ~ '^[a-f0-9]{64}$'),
  active boolean NOT NULL DEFAULT true,
  created_by uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz,
  CHECK ((active AND revoked_at IS NULL) OR (NOT active AND revoked_at IS NOT NULL)),
  UNIQUE(district_id, processor, id)
);
CREATE INDEX commerce_webhook_endpoints_active
  ON commerce_webhook_endpoints(token_sha256) WHERE active;

ALTER TABLE commerce_webhook_endpoints ENABLE ROW LEVEL SECURITY;
ALTER TABLE commerce_webhook_endpoints FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON commerce_webhook_endpoints
  USING (district_id = nullif(current_setting('app.district_id', true), '')::uuid)
  WITH CHECK (district_id = nullif(current_setting('app.district_id', true), '')::uuid);

-- Resolve a random endpoint token to exactly one enabled provider account.
-- The returned credentials remain encrypted; the caller must decrypt using
-- the configured server key. No caller-supplied district/provider selector.
CREATE FUNCTION eduos_commerce_webhook_account(p_token_sha256 text)
RETURNS TABLE (
  district_id uuid,
  processor text,
  mode text,
  config jsonb,
  secrets_enc text,
  fee_bps integer,
  fee_fixed_cents integer
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
  SELECT e.district_id, e.processor, a.mode, a.config, a.secrets_enc,
         a.fee_bps, a.fee_fixed_cents
    FROM public.commerce_webhook_endpoints e
    JOIN public.commerce_provider_accounts a
      ON a.district_id=e.district_id AND a.processor=e.processor
   WHERE e.token_sha256=p_token_sha256
     AND e.active
     AND a.enabled
   LIMIT 1
$$;
REVOKE ALL ON FUNCTION eduos_commerce_webhook_account(text) FROM PUBLIC;
